import{_ as t,o,c as n,aj as a}from"./chunks/framework.C6uXqnaX.js";const c=JSON.parse('{"title":"Hydration with unsupported Zone.js instance","description":"","frontmatter":{},"headers":[],"relativePath":"en/errors/NG05000.md","filePath":"en/errors/NG05000.md"}'),r={name:"en/errors/NG05000.md"};function i(s,e,p,d,u,h){return o(),n("div",null,e[0]||(e[0]=[a('<h1 id="hydration-with-unsupported-zone-js-instance" tabindex="-1">Hydration with unsupported Zone.js instance <a class="header-anchor" href="#hydration-with-unsupported-zone-js-instance" aria-label="Permalink to &quot;Hydration with unsupported Zone.js instance&quot;">​</a></h1><p>This warning means that the hydration was enabled for an application that was configured to use an unsupported version of Zone.js: either a custom or a &quot;noop&quot; one (see more info <a href="https://angular.dev/api/core/BootstrapOptions#ngZone" target="_blank" rel="noreferrer">here</a>).</p><p>Hydration relies on a signal from Zone.js when it becomes stable inside an application, so that Angular can start the serialization process on the server or post-hydration cleanup on the client (to remove DOM nodes that remained unclaimed).</p><p>Providing a custom or a &quot;noop&quot; Zone.js implementation may lead to a different timing of the &quot;stable&quot; event, thus triggering the serialization or the cleanup too early or too late. This is not yet a fully supported configuration.</p><p>If you use a custom Zone.js implementation, make sure that the &quot;onStable&quot; event is emitted at the right time and does not result in incorrect application behavior with hydration.</p><p>More information about hydration can be found in the <a href="/en/guide/hydration">hydration guide</a>.</p>',6)]))}const m=t(r,[["render",i]]);export{c as __pageData,m as default};
